let rawQuery = query;
if (rawQuery && typeof rawQuery === "object" && rawQuery.query) {
  rawQuery = rawQuery.query;
}
let text = String(rawQuery || "").toLowerCase();

// -------------------------
// 0. Arabic support: convert Arabic-Indic digits and map common Arabic words to the English tokens used below
// -------------------------
text = text
  .replace(/[\u0660-\u0669]/g, d => String("\u0660\u0661\u0662\u0663\u0664\u0665\u0666\u0667\u0668\u0669".indexOf(d)))
  .replace(/[\u06f0-\u06f9]/g, d => String("\u06f0\u06f1\u06f2\u06f3\u06f4\u06f5\u06f6\u06f7\u06f8\u06f9".indexOf(d)))
  .replace(/\u0628\u0627\u0631\u0627\u0633\u064a\u062a\u0627\u0645\u0648\u0644|\u0628\u0627\u0631\u0633\u064a\u062a\u0627\u0645\u0648\u0644|\u0628\u0627\u0631\u0627\u0633\u064a\u062a\u0645\u0648\u0644|\u0627\u0633\u064a\u062a\u0627\u0645\u064a\u0646\u0648\u0641\u064a\u0646|\u0623\u0633\u064a\u062a\u0627\u0645\u064a\u0646\u0648\u0641\u064a\u0646|\u0628\u0627\u0646\u0627\u062f\u0648\u0644|\u0628\u0646\u0627\u062f\u0648\u0644/g, " paracetamol ")
  .replace(/(\d+(?:\.\d+)?)\s*(?:\u0643\u062c\u0645|\u0643\u063a\u0645|\u0643\u064a\u0644\u0648\u062c\u0631\u0627\u0645|\u0643\u064a\u0644\u0648 \u062c\u0631\u0627\u0645|\u0643\u064a\u0644\u0648)/g, "$1 kg ")
  .replace(/(\d+(?:\.\d+)?)\s*(?:\u0645\u0644\u062c\u0645|\u0645\u0644\u063a\u0645|\u0645\u062c\u0645|\u0645\u0644\u063a|\u0645\u062c)/g, "$1 mg ")
  .replace(/(\d+(?:\.\d+)?)\s*(?:\u062c\u0631\u0627\u0645|\u063a\u0631\u0627\u0645)/g, "$1 g ")
  .replace(/(\d+(?:\.\d+)?)\s*(?:\u0627\u0642\u0631\u0627\u0635|\u0623\u0642\u0631\u0627\u0635|\u0642\u0631\u0635|\u062d\u0628\u0648\u0628|\u062d\u0628\u0627\u062a|\u062d\u0628\u0629|\u0643\u0628\u0633\u0648\u0644\u0627\u062a|\u0643\u0628\u0633\u0648\u0644\u0629)/g, "$1 tablets ")
  .replace(/(\d+(?:\.\d+)?)\s*(?:\u0633\u0627\u0639\u0627\u062a|\u0633\u0627\u0639\u0629)/g, "$1 hours ago ")
  .replace(/\u0633\u0627\u0639\u062a\u064a\u0646|\u0633\u0627\u0639\u062a\u0627\u0646/g, " 2 hours ago ");

// -------------------------
// 1. Identify substance
// -------------------------
let substance = null;
if (text.includes("paracetamol") || text.includes("acetaminophen")) {
  substance = "Paracetamol";
}

// -------------------------
// 2. Extract number of tablets/units
// Examples:
// 10 tablets
// 12 tab
// took 8 pills
// -------------------------
const quantityMatch = text.match(
  /(\d+(?:\.\d+)?)\s*(?:tablets?|tabs?|pills?|units?)/i
);
const quantity = quantityMatch
  ? Number(quantityMatch[1])
  : null;

// -------------------------
// 3. Extract strength
// Examples:
// 500 mg
// 0.5 g
// -------------------------
const strengthMatch = text.match(
  /(\d+(?:\.\d+)?)\s*(mg|g)\b/i
);
let strengthMg = null;
if (strengthMatch) {
  const value = Number(strengthMatch[1]);
  const unit = strengthMatch[2].toLowerCase();
  strengthMg = unit === "g" ? value * 1000 : value;
}

// -------------------------
// 4. Extract patient weight
// Examples:
// 70 kg
// weighs 60 kg
// weight is 55 kg
// -------------------------
const weightMatch = text.match(
  /(?:weighs?|weight(?:\s+is)?|body\s+weight)?\s*(\d+(?:\.\d+)?)\s*kg\b/i
);
const weightKg = weightMatch
  ? Number(weightMatch[1])
  : null;

// -------------------------
// 5. Extract time since ingestion
// Examples:
// 3 hours ago
// 2.5 hours ago
// -------------------------
const timeMatch = text.match(
  /(\d+(?:\.\d+)?)\s*hours?\s*ago/i
);
const hoursSinceIngestion = timeMatch
  ? Number(timeMatch[1])
  : null;

// -------------------------
// 6. Calculate dose
// -------------------------
let totalDoseMg = null;
let doseMgKg = null;
if (substance && quantity !== null && strengthMg !== null) {
  totalDoseMg = quantity * strengthMg;
}
if (totalDoseMg !== null && weightKg !== null && weightKg > 0) {
  doseMgKg = totalDoseMg / weightKg;
}

// -------------------------
// 7. Identify missing information
// -------------------------
const missingInformation = [];
if (!substance) missingInformation.push("substance");
if (quantity === null) missingInformation.push("number of tablets/units");
if (strengthMg === null) missingInformation.push("strength per tablet/unit");
if (weightKg === null) missingInformation.push("patient weight");
if (hoursSinceIngestion === null) missingInformation.push("time since ingestion");

// -------------------------
// 8. Return structured result
// -------------------------
return JSON.stringify({
  substance,
  quantity,
  strengthMg,
  weightKg,
  hoursSinceIngestion,
  totalDoseMg,
  doseMgKg: doseMgKg !== null
    ? Number(doseMgKg.toFixed(2))
    : null,
  missingInformation,
  note: substance ? null : "Dose NOT calculated: substance not recognised. This calculator supports paracetamol/acetaminophen only."
});

